INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'A WordPress Commenter', 'wapuu@wordpress.example', 'https://wordpress.org/', '', '2026-10-04 14:51:35', '2026-10-04 14:51:35', 'Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0),
(2, 2828, 'Alexander Garcia', 'alexander.garcia50@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:22:52', '2025-04-29 09:22:52', 'Works like a charm! Setup was easy and the product operates exactly as advertised. It\\\'s refreshing to get something that truly delivers on its promises. I highly recommend it to anyone who values quality and wants a smooth, worry-free experience.', 0, '1', '', 'review', 0, 0),
(3, 2831, 'Harper Thompson', 'harper.thompson18@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:22:30', '2025-04-29 09:22:30', 'Very impressed by the quality and performance of this product. Every small detail seems to have been thought through carefully. It’s reliable, efficient, and beautifully designed. I couldn\\\'t be happier. Definitely a five-star experience for me!', 0, '1', '', 'review', 0, 0),
(4, 2834, 'Henry Martin', 'henry.martin85@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:22:12', '2025-04-29 09:22:12', 'This has to be one of the best purchases I’ve made this year. The product works so smoothly, and it feels so well-built. It’s rare to find such high-quality items these days. I’ll be recommending this to everyone I know without a doubt.', 0, '1', '', 'review', 0, 0),
(5, 2837, 'Amelia Harris', 'amelia.harris37@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:21:54', '2025-04-29 09:21:54', 'Great product at a great price. It’s exactly what I needed and has made my daily routine much easier. The craftsmanship is fantastic, and the customer service was also wonderful. A very satisfying experience overall. Would absolutely recommend!', 0, '1', '', 'review', 0, 0),
(6, 2840, 'Lucas White', 'lucas.white64@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:21:39', '2025-04-29 09:21:39', 'Love it! The product’s design is thoughtful, and it’s clear that quality was a priority. Every feature works flawlessly, and it’s been a pleasure to use. Great value for the price and an excellent experience from start to finish. Highly recommend!', 0, '1', '', 'review', 0, 0),
(7, 2845, 'Mia Jackson', 'mia.jackson29@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:21:18', '2025-04-29 09:21:18', 'Brilliant product and fantastic service! The item arrived sooner than expected and was even better in person. It feels sturdy, looks beautiful, and performs as promised. I’m extremely happy and will definitely shop with this seller again.', 0, '1', '', 'review', 0, 0),
(8, 2851, 'Benjamin Thomas', 'benjamin.thomas70@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:21:03', '2025-04-29 09:21:03', 'Exactly as described and better than expected. The product works smoothly, looks amazing, and seems built to last. I appreciate the attention to detail from the seller too. I would recommend this to anyone who wants high quality and great value.', 0, '1', '', 'review', 0, 0),
(9, 2857, 'Isabella Moore', 'isabella.moore81@gmail.com', '', '2405:4802:1cb2:aab0:4496:7ba2:9ce4:f5de', '2025-04-29 09:20:47', '2025-04-29 09:20:47', 'Top-notch quality! The materials feel premium, the performance is fantastic, and the overall design is very appealing. It’s rare these days to find something that meets and exceeds expectations. I would definitely buy this product again.', 0, '1', '', 'review', 0, 0),
(10, 3459, 'Benjamin Thomas', 'benjamin.thomas70@gmail.com', '', '2405:4802:1f2:1870:3d72:9ae9:7298:63b1', '2026-05-25 03:31:26', '2026-05-25 03:31:26', 'Exactly as described and better than expected. The product works smoothly, looks amazing, and seems built to last. I appreciate the attention to detail from the seller too. I would recommend this to anyone who wants high quality and great value.', 0, '1', '', 'review', 0, 0),
(11, 3462, 'Amelia Harris', 'amelia.harris37@gmail.com', '', '2405:4802:1f2:1870:3d72:9ae9:7298:63b1', '2026-05-25 03:30:26', '2026-05-25 03:30:26', 'Great product at a great price. It’s exactly what I needed and has made my daily routine much easier. The craftsmanship is fantastic, and the customer service was also wonderful. A very satisfying experience overall. Would absolutely recommend!', 0, '1', '', 'review', 0, 0);
