(712, '_transient_code_snippets_welcome_data', 'a:5:{s:6:\"banner\";a:9:{s:3:\"key\";s:6:\"bf2025\";s:14:\"start_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-11-18 00:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:12:\"end_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-12-03 00:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:9:\"text_free\";s:63:\"Save up to 50% on Code Snippets Pro with our Black Friday Sale!\";s:15:\"action_url_free\";s:45:\"https://codesnippets.pro/pricing/?cs_user=new\";s:17:\"action_label_free\";s:8:\"Get Deal\";s:8:\"text_pro\";s:58:\"Save up to 50% on your upgrade with our Black Friday Sale!\";s:14:\"action_url_pro\";s:50:\"https://codesnippets.pro/pricing/?cs_user=existing\";s:16:\"action_label_pro\";s:8:\"Get Deal\";}s:9:\"hero-item\";a:3:{s:4:\"name\";s:24:\"Meet Snippet Conditions!\";s:10:\"follow_url\";s:78:\"https://codesnippets.pro/blog/version-3-7-snippet-conditions-official-release/\";s:9:\"image_url\";s:78:\"https://codesnippets.pro/wp-content/uploads/2025/09/conditions_screenshot.webp\";}s:8:\"features\";a:4:{i:0;a:5:{s:5:\"title\";s:28:\"Pssss... Get Secret Discount\";s:10:\"follow_url\";s:22:\"https://snipco.de/TFIG\";s:9:\"image_url\";s:81:\"https://codesnippets.pro/wp-content/uploads/2024/09/Promotions_Hero_All_Plans.png\";s:8:\"category\";s:5:\"offer\";s:11:\"description\";s:100:\"Get secret discount on all Code Snippets Pro plans. Just use coupon code \'General5\' at the checkout!\";}i:1;a:5:{s:5:\"title\";s:25:\"Add Unsplash to WordPress\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mind\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/kRSwWDanX0A/maxresdefault.jpg\";s:8:\"category\";s:3:\"tip\";s:11:\"description\";s:70:\"Code Snippet to Add Unsplash to WordPress - Find and Download Images..\";}i:2;a:5:{s:5:\"title\";s:30:\"Code Snippet Cloud Setup Guide\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mine\";s:9:\"image_url\";s:149:\"https://cdn.getgist.com/attachment_images/76ca6cef08ca8e69ac1e7fbc15004bebbd08ad595ee67e0d7b55d1a9555354bfScreenshot%202023-11-23%20at%2000.50.02.png\";s:8:\"category\";s:5:\"guide\";s:11:\"description\";s:143:\"We have done our best to make the cloud set up as smooth and easy as possible. This guide below will walk you through the process step by step.\";}i:3;a:5:{s:5:\"title\";s:14:\"Cloud and AI +\";s:10:\"follow_url\";s:22:\"https://snipco.de/Minf\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/rEOC2bIwY-w/maxresdefault.jpg\";s:8:\"category\";s:11:\"new feature\";s:11:\"description\";s:68:\"Code Snippets 3.6 Announcement - AI CodeSnippets - Generate AI Code!\";}}s:8:\"partners\";a:4:{i:0;a:3:{s:5:\"title\";s:9:\"Elementor\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3d\";s:9:\"image_url\";s:76:\"https://codesnippets.pro/wp-content/uploads/2024/05/Elementor-logo-green.png\";}i:1;a:3:{s:5:\"title\";s:7:\"InstaWP\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3n\";s:9:\"image_url\";s:68:\"https://codesnippets.pro/wp-content/uploads/2024/05/instawp-logo.png\";}i:2;a:3:{s:5:\"title\";s:11:\"Dynamic.ooo\";s:10:\"follow_url\";s:28:\"https://snipco.de/dynamicooo\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2025/09/Dynamicooo-Logo.png\";}i:3;a:3:{s:5:\"title\";s:10:\"Crocoblock\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3l\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2024/05/crocoblock-logo.png\";}}s:9:\"changelog\";a:4:{i:0;a:3:{s:7:\"version\";s:6:\"3.10.2\";s:4:\"date\";s:17:\"September 1, 2026\";s:7:\"entries\";a:3:{s:5:\"Added\";a:1:{s:4:\"core\";a:1:{i:0;s:121:\"Added a confirmation flow for run-once snippet execution and hardened the handler to prevent failed or confusing actions.\";}}s:7:\"Changed\";a:1:{s:4:\"core\";a:2:{i:0;s:100:\"Snippet names now respect the row truncation Screen Option in the admin list for better readability.\";i:1;s:117:\"Version switching AJAX requests now validate the correct nonce, improving reliability when updating snippet versions.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:6:{i:0;s:79:\"Fixed safe mode fatal errors caused by an undefined wp_get_current_user() call.\";i:1;s:82:\"Fixed PHP validation being triggered incorrectly when activating snippets in bulk.\";i:2;s:49:\"Fixed saving issues after a user session expires.\";i:3;s:82:\"Fixed warnings caused by aliased field names when reading modified snippet fields.\";i:4;s:76:\"Fixed vendor autoloader issues by stripping unprefixed namespace references.\";i:5;s:101:\"Resolved issues where snippet names and version switches could behave inconsistently in the admin UI.\";}}}}i:1;a:3:{s:7:\"version\";s:6:\"3.10.1\";s:4:\"date\";s:15:\"August 28, 2026\";s:7:\"entries\";a:2:{s:7:\"Changed\";a:1:{s:4:\"core\";a:1:{i:0;s:73:\"Enhanced active-link visibility in the toolbar with border-based styling.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:9:{i:0;s:81:\"Fixed a fatal error affecting snippets that use a namespace or declare statement.\";i:1;s:111:\"Fixed the snippets page rendering blank when another plugin\'s screen settings filter returned an invalid value.\";i:2;s:123:\"Fixed snippet saving on hosts that block REST API PUT and PATCH requests, by sending writes as POST with a method override.\";i:3;s:77:\"Fixed the Snippets List Order setting not being applied to the snippets list.\";i:4;s:101:\"Fixed admin bar snippet scripts failing to load on the free version, including on the site front end.\";i:5;s:71:\"Fixed snippet modified dates being sent without the correct UTC offset.\";i:6;s:70:\"Fixed the row truncation screen option not persisting across sessions.\";i:7;s:39:\"Fixed inconsistent sidebar label sizes.\";i:8;s:73:\"Fixed the sticky editor sidebar showing an unwanted horizontal scrollbar.\";}}}}i:2;a:3:{s:7:\"version\";s:6:\"3.10.0\";s:4:\"date\";s:15:\"August 24, 2026\";s:7:\"entries\";a:3:{s:5:\"Added\";a:1:{s:4:\"core\";a:11:{i:0;s:142:\"New admin interface for managing snippets, with a cleaner layout, faster interactions, and a more consistent experience across plugin screens.\";i:1;s:96:\"Card view for browsing snippets, with a view switcher on the snippets table and Community Cloud.\";i:2;s:98:\"Snippet preview modal for viewing snippet code from the snippets table without opening the editor.\";i:3;s:88:\"Automatic hiding of unrelated admin notices from other plugins on Code Snippets screens.\";i:4;s:140:\"Admin bar snippet drawer, based on the Deckerweb Snippets workflow, for quick access to snippets and Safe Mode from the WordPress admin bar.\";i:5;s:128:\"Snippet locking to help prevent accidental edits or deletion of important snippets. Props to https://github.com/mgiannopoulos24.\";i:6;s:141:\"Improved screen options on the main snippets table, including controls for visible columns and truncating long snippet names or descriptions.\";i:7;s:77:\"Bulk actions and bulk code download support in the redesigned snippets table.\";i:8;s:59:\"Featured snippets and improved browsing in Community Cloud.\";i:9;s:51:\"WordPress modern theme admin styling compatibility.\";i:10;s:132:\"Clearer accessibility labels, headings, tab markup, table checkboxes, sort buttons, copy buttons, and drag-and-drop upload controls.\";}}s:7:\"Changed\";a:1:{s:4:\"core\";a:8:{i:0;s:121:\"Redesigned the main snippets table with improved search, filtering, sorting, pagination, row actions, and bulk selection.\";i:1;s:132:\"Improved the snippet import and migration experience, including clearer file upload handling and third-party plugin migration flows.\";i:2;s:117:\"Improved snippet error handling so activation failures, validation errors, and stack traces are easier to understand.\";i:3;s:126:\"Improved Community Cloud search and filtering, including server-side filters, better result loading, and clearer empty states.\";i:4;s:104:\"Updated the welcome screen, toolbar, import screen, and cloud screens to match the new admin experience.\";i:5;s:103:\"Updated internal plugin architecture to a cleaner PSR-4 structure for better long-term maintainability.\";i:6;s:158:\"Improved accessibility across the snippets table, import screen, migration flow, Community Cloud, welcome screen, toolbar, dialogs, tooltips, and code editor.\";i:7;s:73:\"Improved colour contrast and reduced-motion support across admin screens.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:8:{i:0;s:58:\"Fixed REST API server error responses on missing snippets.\";i:1;s:62:\"Fixed redundant frontend logic, improving overall performance.\";i:2;s:88:\"Fixed Community Cloud search results and pagination to respect WordPress screen options.\";i:3;s:93:\"Fixed snippet saving and activation feedback to improve validation and runtime error display.\";i:4;s:90:\"Fixed downloaded Community Cloud snippets appearing as not downloaded after a page reload.\";i:5;s:74:\"Fixed network snippet lookups using the wrong database table on multisite.\";i:6;s:61:\"Fixed the inactive snippets count including trashed snippets.\";i:7;s:86:\"Fixed featured Community Cloud snippets failing to load with some cloud API responses.\";}}}}i:3;a:3:{s:7:\"version\";s:5:\"3.9.6\";s:4:\"date\";s:14:\"April 28, 2026\";s:7:\"entries\";a:1:{s:5:\"Fixed\";a:1:{s:4:\"core\";a:2:{i:0;s:53:\"Improved permissions handling with snippets REST API.\";i:1;s:56:\"Site admin cannot toggle shared network snippets status.\";}}}}}}', 'off'),
