(1079, '_transient_glozin_cache_glozin_dynamic_css', 'body {--gz-color-primary:#d0473e; --gz-link-color-hover:#d0473e;}.header-logo > a img, .header-logo > a svg {width: 100px;height: 43px;}.site-header__desktop .header-main { --gz-header-main-bg-color: #000000; --gz-header-sticky-bg-color: #000000; }.site-header__desktop .header-main { --gz-header-main-border-color: #ffffff1a; }.site-header__desktop .header-bottom { --gz-header-bottom-bg-color: #000000; --gz-header-sticky-bg-color: #000000; }.site-header__desktop .header-bottom { --gz-header-color: #ffffff; --gz-header-sticky-color: #ffffff; color: #ffffff; }@media (max-width: 1199px) { .site-header__mobile { display: block !important; } }@media (max-width: 1199px) { .site-header__desktop { display: none !important; } }.site-header__mobile .header-mobile-main { --gz-header-main-bg-color: #005461; --gz-header-sticky-bg-color: #005461; }.site-header__mobile .header-mobile-bottom { --gz-header-bottom-bg-color: #005461; --gz-header-sticky-bg-color: #005461; }.campaign-bar { --gz-campaign-background: #49633f; }.topbar { --gz-background-color: #000000; }.topbar { --gz-topbar-border-width: 1px;}.topbar { --gz-topbar-border-color: #ffffff1a;}@media (max-width: 1024px) {\n				.topbar:not(.topbar-mobile) {\n					display: none;\n				}\n				.topbar-mobile .topbar-items {\n					flex: 0 1 auto;\n				}\n				.topbar-mobile--keep-left .topbar-right-items {\n					display: none;\n				}\n				.topbar-mobile--keep-left .topbar-container {\n					justify-content: center;\n				}\n				.topbar-mobile--keep-right .topbar-left-items {\n					display: none;\n				}\n				.topbar-mobile--keep-right .topbar-container {\n					justify-content: center;\n				}\n				.topbar-mobile--keep-all .topbar-container {\n					overflow: hidden;\n					overflow-x: auto;\n				}\n				.topbar-mobile--keep-left .topbar-slides,\n				.topbar-mobile--keep-right .topbar-slides {\n					max-width: 100vw;\n					text-align: center;\n				}\n			}@media (min-width: 1025px) and (max-width: 1300px) {\n				.topbar-items { flex: none; }\n			}:root{--gz-image-rounded:15px;}:root {--gz-button-bg-color:#005461;}.gz-button-light{--gz-button-bg-color-hover:#005461;--gz-button-eff-bg-color-hover:#005461;}:root { --wcboost-variation-swatches-label-shape: 3px; }:root {--product-image-ratio-percent:150%;--gz-image-rounded-product-card:15px;}.single-product div.product {\r\n				--gz-product-description-lines: 3;\r\n			}', 'off'),
