(1566, 3516, '_elementor_data', '[{\"id\":\"5c5912b3\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"flex_direction_tablet\":\"column\"},\"elements\":[{\"id\":\"5b1d7080\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"25\"},\"width_tablet\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]}},\"elements\":[],\"isInner\":true},{\"id\":\"18d0e7e7\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"width_tablet\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"flex_gap\":{\"column\":\"10\",\"row\":\"10\",\"isLinked\":true,\"unit\":\"px\",\"size\":10}},\"elements\":[{\"id\":\"3b9fd5f6\",\"elType\":\"widget\",\"settings\":{\"title\":\"1. Introduction\",\"title_size\":\"h6\"},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"3ee8fb38\",\"elType\":\"widget\",\"settings\":{\"editor\":\"Welcome to https://wpglozin.com/ (“we”, “our”, or “the store”). This Privacy Policy explains how we collect, use, and protect your personal information when you shop with us online for fashion products.\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"63275b84\",\"elType\":\"widget\",\"settings\":{\"title\":\"2. Information We Collect\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"2d57b92b\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<ul><li><strong>Personal Information:</strong> Your name, email, phone number, shipping and billing address.</li><li><strong>Order Details:</strong> Items you purchase, shopping history, and return/exchange requests.</li><li><strong>Payment Information:</strong> We do not store card details. All payments are processed securely via third-party gateways.</li><li><strong>Technical Data:</strong> IP address, browser type, device details, and browsing behavior collected through cookies and analytics tools.</li></ul>\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"5a17749a\",\"elType\":\"widget\",\"settings\":{\"title\":\"3. How We Use Your Information\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"-7\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"518c114\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<ul>\\n      <li>To process and deliver your orders quickly and accurately.</li>\\n      <li>To send order updates, promotions, and customer service messages.</li>\\n      <li>To analyze user behavior and improve your shopping experience.</li>\\n      <li>To personalize content and product recommendations.</li>\\n    </ul>\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"78e97c96\",\"elType\":\"widget\",\"settings\":{\"title\":\"4. Sharing Your Information\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"-7\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"2d0d9969\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>We do not sell or rent your personal data. We may share your information only with:</p><ul><li>Delivery partners to ship your orders.</li><li>Payment providers to process transactions securely.</li><li>Legal authorities when required by law.</li></ul>\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"5b8fd142\",\"elType\":\"widget\",\"settings\":{\"title\":\"5. Cookies and Tracking Technologies\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"-7\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"1f06f570\",\"elType\":\"widget\",\"settings\":{\"editor\":\"We use cookies to remember your cart, recommend products, and analyze website performance. You can manage cookie settings in your browser.\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"6e0e9afe\",\"elType\":\"widget\",\"settings\":{\"title\":\"6. Data Security\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"142e6494\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<ul><li>Promotional codes must be applied at checkout and cannot be added after the order is placed.</li><li>Each promotional code is valid for a limited time and may only be used once unless otherwise stated.</li><li>Discounts cannot be combined with other offers unless explicitly mentioned.</li><li>We reserve the right to cancel any promotional campaign or reject discount code misuse at our discretion.</li></ul>\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"64eb6ae2\",\"elType\":\"widget\",\"settings\":{\"title\":\"7. Privacy Policy\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"-7\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"1e192143\",\"elType\":\"widget\",\"settings\":{\"editor\":\"We implement industry-standard security measures such as SSL encryption, firewalls, and limited access to safeguard your information.\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"70d77215\",\"elType\":\"widget\",\"settings\":{\"title\":\"8. Third-Party Links\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"56b848d8\",\"elType\":\"widget\",\"settings\":{\"editor\":\"Our website may contain links to third-party websites (e.g., social media, delivery services). We are not responsible for their privacy practices or content.\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"3f2c4a42\",\"elType\":\"widget\",\"settings\":{\"title\":\"9. Contact Information\",\"title_size\":\"h6\",\"_margin\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"glozin-heading\"},{\"id\":\"9ee7414\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>If you have any questions regarding this Privacy Policy, please contact us at <a style=\\\"text-decoration: underline;\\\" href=\\\"mailto:support@fashionstore.com\\\">support@fashionstore.com</a>.</p>\",\"text_color\":\"#111111\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"7f1f66a2\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"25\"}},\"elements\":[],\"isInner\":true}],\"isInner\":false}]'),
