INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `condition_id`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 0, 10, 0, '2026-10-05 04:46:19', 1, NULL),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 0, 10, 0, '2026-10-05 04:46:19', 1, NULL),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 0, 10, 0, '2026-10-05 04:46:19', 1, NULL),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 0, 10, 0, '2026-10-05 04:46:19', 1, NULL),
(5, 'MODENA WhatsApp CTA', '', 'add_action(\'woocommerce_single_product_summary\', function () {\n    global $product;\n\n    if (!($product instanceof WC_Product)) {\n        return;\n    }\n\n    $phone = \'6285641818823\';\n\n    $product_name = wp_strip_all_tags($product->get_name());\n    $product_url  = get_permalink($product->get_id());\n\n	$message = \"Halo, saya tertarik dengan produk \"\n		. $product_name\n		. \".\\n\\nLihat produk:\\n\"\n		. $product_url;\n\n    $whatsapp_url = \'https://wa.me/\' . $phone\n        . \'?text=\' . rawurlencode($message);\n\n    ?>\n    <a\n        class=\"button modena-whatsapp-cta\"\n        href=\"<?php echo esc_url($whatsapp_url); ?>\"\n        target=\"_blank\"\n        rel=\"noopener noreferrer\"\n        data-product-id=\"<?php echo esc_attr($product->get_id()); ?>\"\n        data-product-name=\"<?php echo esc_attr($product_name); ?>\"\n        data-product-url=\"<?php echo esc_url($product_url); ?>\"\n        style=\"display:block;text-align:center;background:#128c7e;\n               color:#fff;padding:14px 20px;margin:16px 0;\n               border-radius:25px;\"\n    >\n        Chat via WhatsApp\n    </a>\n    <?php\n}, 35);\n\nadd_action(\'wp_footer\', function () {\n    if (!function_exists(\'is_product\') || !is_product()) {\n        return;\n    }\n\n    ?>\n    <script>\n    document.addEventListener(\'click\', function (event) {\n        if (!(event.target instanceof Element)) {\n            return;\n        }\n\n        const button = event.target.closest(\'.modena-whatsapp-cta\');\n\n        if (!button) {\n            return;\n        }\n\n        console.log(\'Mock analytics event\', {\n            event: \'whatsapp_cta_click\',\n            product_id: button.dataset.productId,\n            product_name: button.dataset.productName,\n            product_url: button.dataset.productUrl,\n            timestamp: new Date().toISOString()\n        });\n    });\n    </script>\n    <?php\n});', '', 'global', 0, 10, 1, '2026-10-05 06:10:31', 1, NULL),
(6, 'MODENA Product Inquiry', '', 'add_action(\'woocommerce_after_single_product_summary\', function () {\n    // Hanya tampil pada produk KS 3290 GTBE.\n    if (get_queried_object_id() !== 3462) {\n        return;\n    }\n\n    if (!shortcode_exists(\'contact-form-7\')) {\n        return;\n    }\n\n    echo \'<section class=\"modena-product-inquiry\"\n        aria-labelledby=\"modena-inquiry-title\"\n        style=\"width:100%; margin:30px 0; padding:24px;\n        border:1px solid #e5e5e5; border-radius:12px;\">\';\n\n    echo \'<h2 id=\"modena-inquiry-title\">Product Inquiry</h2>\';\n    echo \'<p>Have a question about this product? Complete the form below.</p>\';\n\n    echo do_shortcode(\n        \'[contact-form-7 id=\"d298e2f\" title=\"Product Inquiry\"]\'\n    );\n\n    echo \'</section>\';\n}, 5);', '', 'global', 0, 10, 1, '2026-10-06 01:53:35', 1, NULL);
